let output = $json.output;

// Remove ```json and ```
output = output.replace(/```json/g, "").replace(/```/g, "").trim();

return [{
  json: JSON.parse(output)
}];

const data = $json;

const {
  name,
  email,
  total_score,
  max_score,
  percentage,
  result,
  feedback,
  questions_review
} = data;

const isPass = result === "pass";

// SAFE COLORS (email friendly)
const textMain = "#e5e7eb";
const textWhite = "#ffffff";
const muted = "#94a3b8";

const resultColor = isPass ? "#22c55e" : "#ef4444";

const resultMessage = isPass
  ? "Congratulations! You have successfully passed the assessment."
  : "We appreciate your effort You can improve and try again.";

// QUESTIONS
let questionRows = "";

questions_review.forEach((q) => {
  const scoreColor = q.score === q.max_score ? "#22c55e" : "#f97316";

  questionRows += `
  <tr>
    <td style="padding:0 0 18px 0;">

      <div style="
        background:#0b1220;
        border:1px solid #1f2937;
        border-radius:10px;
        padding:15px;
        color:${textMain};
      ">

        <!-- QUESTION -->
        <p style="
          margin:0 0 12px 0;
          color:${textWhite};
          font-size:14px;
          font-weight:600;
          line-height:1.5;
        ">
          Q${q.question_no}. ${q.question}
        </p>

        <!-- YOUR ANSWER -->
        <p style="margin:6px 0; color:${textMain};">
          <span style="color:#60a5fa; font-weight:600;">Your Answer:</span>
          ${q.candidate_answer || "Not Answered"}
        </p>

        <!-- CORRECT ANSWER -->
        <p style="margin:6px 0; color:${textMain};">
          <span style="color:#a78bfa; font-weight:600;">Correct Answer:</span>
          ${q.correct_answer || "-"}
        </p>

        <!-- SCORE -->
        <p style="margin:6px 0; color:${textMain};">
          <span style="color:#facc15; font-weight:600;">Score:</span>
          <span style="color:${scoreColor}; font-weight:bold;">
            ${q.score} / ${q.max_score}
          </span>
        </p>

        <!-- FEEDBACK -->
        <p style="
          margin-top:10px;
          font-size:12px;
          color:${muted};
          border-top:1px solid #1f2937;
          padding-top:10px;
          line-height:1.4;
        ">
          ${q.feedback}
        </p>

      </div>

    </td>
  </tr>
  `;
});

// HTML
const html = `
<!DOCTYPE html>
<html>
<body style="
  margin:0;
  padding:0;
  background-color:#0f172a;
  font-family:Arial, sans-serif;
  color:${textMain};
">

<table width="100%" cellpadding="0" cellspacing="0" style="padding:20px;">
<tr>
<td align="center">

<table width="650" cellpadding="0" cellspacing="0" style="
  background-color:#1e293b;
  border-radius:12px;
  padding:30px;
  color:${textMain};
">

<!-- TITLE -->
<tr>
<td style="text-align:center;">
<h2 style="margin:0; color:${textWhite};">
 Assessment Result Report
</h2>
</td>
</tr>

<!-- GREETING -->
<tr>
<td style="padding-top:20px;">
<p style="margin:0; color:${textMain};">
Hi <strong style="color:${textWhite};">${name}</strong>,
</p>
</td>
</tr>

<!-- RESULT -->
<tr>
<td style="padding-top:10px;">
<p style="margin:0; color:${textMain}; line-height:1.6;">
${resultMessage}
</p>
</td>
</tr>

<!-- SCORE BOX -->
<tr>
<td style="
  margin-top:15px;
  padding:15px;
  background:#0f2a4a;
  border-radius:10px;
  color:${textMain};
">
<p style="margin:0;">
<strong style="color:${textWhite};">Total Score:</strong> ${total_score} / ${max_score}<br>

<strong style="color:${textWhite};">Percentage:</strong> ${percentage}%<br>

<strong style="color:${textWhite};">Result:</strong>
<span style="color:${resultColor}; font-weight:bold; text-transform:uppercase;">
${result}
</span>
</p>
</td>
</tr>

<!-- SECTION -->
<tr>
<td style="padding-top:25px;">
<h3 style="margin:0; color:${textWhite};">
Detailed Evaluation
</h3>
</td>
</tr>

<!-- QUESTIONS -->
<tr>
<td>
<table width="100%" style="border-collapse:collapse; margin-top:15px;">
${questionRows}
</table>
